// Node: Build Daily Summary
// Builds one row per company processed today, marks it Sent or Not Sent,
// and gives a plain-English reason when it wasn't sent. Renders as a
// color-coded HTML table so you can scan it at a glance.

const queuedToday = $('Filter').all().map(item => item.json.company_name);
const currentRows = $input.all().map(item => item.json);

const reasonMap = {
  'inferred': 'Contact email unconfirmed — a guessed pattern, not a verified address',
  'none': 'No credible contact information found',
  'format_invalid': 'Contact email address was malformed — needs manual correction',
  'send_error': 'Email failed to send (Gmail error) — check the address and try manually'
};

let rows = [];
let sentCount = 0;
let notSentCount = 0;

for (const name of queuedToday) {
  const row = currentRows.find(r => (r.company_name || '').trim().toLowerCase() === (name || '').trim().toLowerCase());

  if (!row) {
    rows.push({ company: name, sent: false, reason: 'Not found in sheet \u2014 check manually' });
    notSentCount++;
    continue;
  }

  if (row.status === 'Sent') {
    rows.push({ company: name, sent: true, reason: '' });
    sentCount++;
  } else if (row.status === 'Needs manual review') {
    const reason = reasonMap[row.confidence] || `Held for review (confidence: ${row.confidence || 'unknown'})`;
    rows.push({ company: name, sent: false, reason: reason });
    notSentCount++;
  } else {
    rows.push({ company: name, sent: false, reason: 'Processing did not complete \u2014 check the workflow execution log' });
    notSentCount++;
  }
}

const today = new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });

const tableRows = rows.map(r => {
  const bg = r.sent ? '#d9f2d9' : '#fbdcdc';
  const statusText = r.sent ? 'Sent' : 'Not Sent';
  const statusColor = r.sent ? '#1a7a1a' : '#b30000';
  return `<tr style="background-color:${bg};">
    <td style="padding:8px 12px; border:1px solid #ccc;">${r.company}</td>
    <td style="padding:8px 12px; border:1px solid #ccc; color:${statusColor}; font-weight:bold;">${statusText}</td>
    <td style="padding:8px 12px; border:1px solid #ccc;">${r.reason}</td>
  </tr>`;
}).join('');

const html = `
<div style="font-family:Arial, sans-serif; font-size:14px; color:#222;">
  <h2 style="margin-bottom:4px;">Daily Outbound Pitch Agent Summary \u2014 ${today}</h2>
  <p style="margin-top:0;">Total processed: ${queuedToday.length} &nbsp;|&nbsp; Sent: ${sentCount} &nbsp;|&nbsp; Not sent: ${notSentCount}</p>
  <table style="border-collapse:collapse; width:100%; margin-top:12px;">
    <tr style="background-color:#333; color:#fff;">
      <th style="padding:8px 12px; text-align:left;">Company</th>
      <th style="padding:8px 12px; text-align:left;">Status</th>
      <th style="padding:8px 12px; text-align:left;">Reason (if not sent)</th>
    </tr>
    ${tableRows}
  </table>
</div>`;

return [{
  json: {
    summary_subject: `Pitch Agent Summary \u2014 ${sentCount} sent, ${notSentCount} not sent (${today})`,
    summary_body: html
  }
}];

// Node: Filter Out Duplicates
// Removes any company already in the sheet, AND removes any company
// that appears more than once within this same newly-found batch
// (keeping only the first occurrence).

const existingNames = new Set(
  $('Read All Prospects').all().map(item => (item.json.company_name || '').toLowerCase().trim())
);

const seenThisBatch = new Set();
const output = [];

for (const item of $input.all()) {
  const name = (item.json.company_name || '').toLowerCase().trim();
  if (!name) continue;                    // drops malformed/blank rows
  if (existingNames.has(name)) continue;   // already on the sheet
  if (seenThisBatch.has(name)) continue;   // duplicate within today's batch
  seenThisBatch.add(name);
  output.push(item);
}

return output;
